from dataclasses import dataclass, field


@dataclass
class OrderLine:
    sku: str
    qty: int
    unit_cents: int

    @property
    def total_cents(self) -> int:
        return self.qty * self.unit_cents


@dataclass
class Parcel:
    order_id: str
    lines: list[OrderLine]
    gift_message: str = ""

    @property
    def total_weight_g(self) -> int:
        # Placeholder for weight calculation; in a real system this would be derived from SKU weights
        return sum(line.qty * 100 for line in self.lines)


@dataclass
class Order:
    id: str
    lines: list[OrderLine] = field(default_factory=list)
    currency: str = "USD"
    gift_message: str = ""

    @property
    def total_cents(self) -> int:
        return sum(line.total_cents for line in self.lines)

    def split_into_parcels(self) -> list[Parcel]:
        """
        Splits the order into parcels.
        The gift message is carried through to the first parcel only.
        """
        if not self.lines:
            return []

        # For simplicity, this implementation puts all lines in a single parcel.
        # A more complex logic might split based on warehouse or weight,
        # but the requirement is that the message goes to the *first* parcel.
        return [
            Parcel(
                order_id=self.id,
                lines=self.lines,
                gift_message=self.gift_message
            )
        ]


def packing_slip(parcel: Parcel, weight_g: int) -> str:
    """
    Generates the packing slip text for a parcel.
    Includes the gift message if present.
    """
    lines = []
    lines.append(f"PACKING SLIP - Order: {parcel.order_id}")
    lines.append(f"Weight: {weight_g}g")
    lines.append("-" * 20)
    for line in parcel.lines:
        lines.append(f"{line.sku} x {line.qty} @ {line.unit_cents/100:.2f}")
    if parcel.gift_message:
        lines.append("-" * 20)
        lines.append(f"Gift Message: {parcel.gift_message}")
    return "\n".join(lines)


def customer_invoice(order: Order) -> str:
    """
    Generates the customer invoice text.
    Must NOT include the gift message.
    """
    lines = []
    lines.append(f"INVOICE - Order: {order.id}")
    lines.append(f"Currency: {order.currency}")
    lines.append("-" * 20)
    for line in order.lines:
        lines.append(f"{line.sku} x {line.qty} @ {line.unit_cents/100:.2f}")
    lines.append("-" * 20)
    lines.append(f"Total: {order.total_cents/100:.2f}")
    return "\n".join(lines)
